            next_assignment = dict(assignment)
            next_assignment[name] = row
            next_required = required | set(row.get('deps', []))
            visit(next_assignment, next_required)

    visit({}, set(roots))
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {
        'versions': {
            name: best_assignment[name]['version']
            for name in best_assignment
        }
    }
